import json
from pathlib import Path
P=Path(__file__).resolve().parent
rs=json.loads((P/'remaining-initial.json').read_text());done={x['Form_ID'] for f in P.glob('pass*-saved-assignments.json') for x in json.loads(f.read_text())}
groups=[{'parent': '6943', 'gloss': ['river'], 'forms': ['nɔ', 'nō̃i', 'ˈnoh', 'nā', 'noye', 'nɔye', 'nan', 'nīn'], 'languages': ['jaun', 'kul', 'DungraBhili', 'Bshk'], 'citation': 'CDIAL[6943 and addenda]', 'evidence': 'Turner gives Jaunsari naī/nau, Kiunthal nɔ̈/nɔe, Marathi nahī and the nasalized Dardic family including Bashkarik nanda and Gawri nendi. The survey contracted Pahari/Bhili and Bashkarik nan/nīn forms fit those documented river-word developments. This rule excludes retained-d plains forms and multiword river expressions.'}, {'parent': '3981', 'gloss': ['river'], 'forms': ['gaḍ', 'gāḍ'], 'languages': ['jaun', 'kul'], 'citation': 'CDIAL[3981]', 'evidence': 'Turner explicitly lists western Pahari gaḍḍ river/stream and its suffixed gaḍḍṛī/gaḍōṛ variants under *gaḍḍa. The Jaunsari and Kullui gaḍ/gāḍ river forms belong to this regional watercourse sense, with vowel length retained; no generic pit meaning is imposed.'}, {'parent': '4137', 'gloss': ['mud'], 'forms': ['gāru', 'garū', 'gārū', 'gārā', 'gar'], 'citation': 'CDIAL[4137 and addenda]', 'evidence': 'Turner gives Gujarati gār/gārɔ prepared clay, Hindi gārā mud/mortar and explicitly Jaunsari gārā and Kotgarhi gār/garɔ mixed mud. These survey gār-/gar- forms match the plain-r mud family. Retroflex gāṛ- and aspirated ghāṛ- responses are excluded because Turner has other competing mud/thickness entries for them.'}, {'parent': '2869', 'gloss': ['mud'], 'forms': ['kādevaḍū', 'kādevaḷū', 'kādevḍū', 'kādɛūḍo', 'khādɛūḍu', 'kādāvḍɔ', 'kādavḍo', 'kādaūḍā', 'kādeūḍā'], 'citation': 'CDIAL[2869]', 'evidence': 'Turner gives Gujarati kādav mud under kardama, beside Middle Indo-Aryan kaddama and Hindi kādaw. These Bhili-area forms preserve the diagnostic intervocalic v or its vocalic trace before a diminutive ḍ suffix. The kād- family comparison is secure at this level; expressive suffix and occasional aspiration are qualifications, and bare eastern kāda forms are excluded because karda competes.'}, {'parent': '14118', 'gloss': ['mud'], 'forms': ['hil'], 'languages': ['jaun'], 'citation': 'CDIAL[14118]', 'evidence': 'Turner records Kumaoni hīl/hīlo, Nepali hilo and Hindi hīl/hīlā mud under *hilla², with western Pahari helo clayey as a nearby comparison. Jaunsari hil mud matches this regional noun directly.'}, {'parent': '9530-7', 'gloss': ['bad'], 'forms': ['bhūṇḍlo', 'bhūnḍɔt', 'bhūṇḍan', 'bhūnḍuj', 'būṇḍo'], 'languages': ['Bhilali', 'Bhili'], 'citation': 'CDIAL[9530,7]', 'evidence': 'Turner’s seventh *bhuṇḍa branch explicitly includes Gujarati bhũḍũ bad and Hindi bhū̃ḍā ugly. The Bhili survey nasal-retroflex-ḍ forms fit this Gujarati-border bad adjective family, with local endings preserved. The ṭ form and northern Punjabi-like bhuṇḍā forms are excluded because Turner assigns competing branches there.'}]
a=[]
for i,g in enumerate(groups):
 for r in rs:
  if r['ID'] not in done and r['Gloss'] in g['gloss'] and r['Form'] in g['forms'] and ('languages' not in g or r['Language_ID'] in g['languages']):
   x=dict(record=r,citation=g['citation'],evidence=g['evidence'],family=i)
   if 'components' in g:x['components']=g['components']
   else:x.update(parent=g['parent'],kind=g.get('kind','reflex'))
   a.append(x)
assert len(a)==len({x['record']['ID'] for x in a})
h=[]
(P/'pass050-decisions.json').write_text(json.dumps(dict(accepted=a,held=h),ensure_ascii=False,indent=1)+'\n')
(P/'pass050-rules.json').write_text(json.dumps(groups,ensure_ascii=False,indent=1)+'\n')
print(len(a),'accepted',len(h),'held',[(g.get('parent',g.get('components')),sum(x['family']==i for x in a)) for i,g in enumerate(groups)])
